import { strict as assert } from "node:assert";
import { test } from "node:test";
import { delays } from "./retry.mjs";

test("doubles the wait before each attempt", () => {
  assert.deepEqual(delays(4), [1, 2, 4, 8]);
});

test("waits for nothing when no attempt is allowed", () => {
  assert.deepEqual(delays(0), []);
});

